arguments.command:
cd /tmp/vally-eval-trial-S9ZqsL && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Gold
}

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var payable = new CalculatePayableTotalHandler().Handle(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | grep -v '^\s*$' | head -25

